create table events (id bigint generated by default as identity primary key, name text not null, event_date date not null, status text default 'ブッキング中', open_time time, start_time time, venue text, promoter text, advance_price integer, door_price integer, created_at timestamptz default now());
create table artists (id bigint generated by default as identity primary key, name text not null, contact_name text, email text, phone text, notes text, created_at timestamptz default now());
create table bookings (id bigint generated by default as identity primary key, event_id bigint references events(id) on delete cascade, artist_id bigint references artists(id) on delete cascade, status text default 'オファー中', performance_time time, fee integer, offer_date date, created_at timestamptz default now());
create table tasks (id bigint generated by default as identity primary key, event_id bigint references events(id) on delete cascade, title text not null, due_date date, completed boolean default false, created_at timestamptz default now());
